import{_ as o,o as t,c as r,a3 as l}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Resellers — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Resellers — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/resellers"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Resellers — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/resellers"}]]},"headers":[],"relativePath":"deployment/resellers.md","filePath":"deployment/resellers.md","lastUpdated":1786813920000}'),s={name:"deployment/resellers.md"};function a(i,e,n,d,c,m){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="resellers-—-production-guide" tabindex="-1">Resellers — Production Guide <a class="header-anchor" href="#resellers-—-production-guide" aria-label="Permalink to &quot;Resellers — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>resellers</code></li><li>Category: <code>sales</code> (<strong>Sales</strong>), <code>category_sort_order = 20</code>, module <code>sort_order = 70</code></li><li><strong>Free Marketplace opt-in</strong> (<code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>)</li><li>Hard dependency: <strong>Payments</strong> (<code>module_dependencies</code>, not optional)</li><li>New workspaces receive only <strong>Leads</strong> + <strong>Tasks</strong> by default; enable Payments, then Resellers from Marketplace</li><li>Deactivate via Central module subscription tools to revoke access without dropping data</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create (Central tenant create or public register):</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules (<strong>Leads</strong>, <strong>Tasks</strong> only)</li><li>Operators enable Payments, then Resellers from Marketplace</li><li>Tenant permissions include <code>resellers.*</code> via data migration + default role maps</li><li>Protected default role <code>reseller</code> is ensured for every tenant (<code>ensure_reseller_default_role</code> migration)</li></ol><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Resellers permissions for <strong>existing</strong> workspaces ship as additive data migrations:</p><ul><li><code>2026_08_06_100004_add_resellers_permissions</code> — <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions</code></li><li><code>2026_08_06_100009_ensure_reseller_default_role</code> — creates missing <code>reseller</code> role + grants view permissions</li></ul><p>Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><h2 id="schema-migrations" tabindex="-1">Schema migrations <a class="header-anchor" href="#schema-migrations" aria-label="Permalink to &quot;Schema migrations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Migration</th><th>Purpose</th></tr></thead><tbody><tr><td><code>2026_08_06_100000_create_resellers_table</code></td><td><code>resellers</code></td></tr><tr><td><code>2026_08_06_100001_add_reseller_id_to_customer_invoices_table</code></td><td>nullable FK on <code>customer_invoices</code></td></tr><tr><td><code>2026_08_06_100003_register_resellers_module</code></td><td>catalog via <code>DefaultModuleRegistrar</code></td></tr><tr><td><code>2026_08_06_100005_add_resellers_payments_dependency</code></td><td>hard dep → payments</td></tr></tbody></table><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit: <code>reseller_created</code>, <code>reseller_updated</code>, <code>reseller_deleted</code>, <code>reseller_assigned</code>, <code>reseller_login_invited</code></li><li>Spatie activity log name: <code>resellers</code></li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate schema + catalog + permissions + Payments dependency (migrate-only; no <code>db:seed</code> in production)</li><li>Confirm <code>module:resellers</code> + <code>resellers.*</code> on target roles; confirm protected <code>reseller</code> role exists</li><li>Confirm Marketplace blocks Resellers install without Payments</li><li>Smoke: enable Payments → Resellers → create reseller → set rates → invite login → link on invoice</li><li>Frontend: deploy Sales nav when SPA milestone ships</li></ol><h2 id="deferred" tabindex="-1">Deferred <a class="header-anchor" href="#deferred" aria-label="Permalink to &quot;Deferred&quot;">​</a></h2><p>Cross-workspace reseller identity remains out of Phase 1 — invite-login is same-tenant only.</p>',18)])])}const _=o(s,[["render",a]]);export{u as __pageData,_ as default};
